import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import{createHash}from'node:crypto';import{pathToFileURL}from'node:url';
import{BUNDLED_FONT_MANIFEST}from'../src/shared/fonts/index.js';
import{loadBundledFontCatalog,sharedBundledFontCatalog}from'../src/renderer/features/personalization/bundled-font-loader.js';
import{mountFontPicker,validateFontFaceSelection}from'../src/renderer/features/personalization/font-picker.js';
const receipt=()=>({default:{schemaVersion:1,identity:createHash('sha256').update(JSON.stringify(BUNDLED_FONT_MANIFEST)).digest('hex'),status:'staged-not-rendered',assets:BUNDLED_FONT_MANIFEST.assets.map(({name,bytes,sha256})=>({name,bytes,sha256}))}});
const baseURL=pathToFileURL(process.cwd()+'/src/renderer/fonts/').href;
function runtime({fail=0,controller}={}){const calls=[];class Face{constructor(family,source,options){this.family=family;calls.push({family,source,options});}async load(){if(fail&&calls.length===fail)throw Error('Local font decode rejected');if(controller&&calls.length===2)controller.abort();return this;}}const doc={fonts:new Set(),defaultView:{FontFace:Face}};return{doc,calls,options:{baseURL,document:doc,loadReceipt:async()=>receipt()}};}
test('actual local font loader admits exact receipt and maps three alias consumers without claiming rendered identity',async()=>{const f=runtime(),catalog=await loadBundledFontCatalog(f.options);assert.equal(f.calls.length,3);assert.equal(f.doc.fonts.size,3);assert.equal(catalog.status,'loaded-not-rendered');assert.deepEqual(f.calls.map(row=>row.family),['MFE Noto Sans Regular','MFE Noto Sans Italic','MFE Noto Sans CJK HK']);assert.equal(f.calls[1].options.style,'italic');assert.ok(f.calls.every(row=>row.source.startsWith('url("file:')));for(const face of catalog.faces)assert.ok(validateFontFaceSelection(face,catalog));assert.throws(()=>validateFontFaceSelection({...catalog.faces[1],mapping:{...catalog.faces[1].mapping,verified:false}},catalog),/exact face/);catalog.destroy();assert.equal(f.doc.fonts.size,0);});
test('wrong receipt, missing staging, partial load and cancellation cannot admit fonts',async()=>{for(const mutate of [value=>value.default.identity='0'.repeat(64),value=>value.default.assets.pop(),value=>value.default.assets[0].sha256='0'.repeat(64)]){const f=runtime(),bad=receipt();mutate(bad);await assert.rejects(loadBundledFontCatalog({...f.options,loadReceipt:async()=>bad}),/receipt differs/);assert.equal(f.calls.length,0);}const absent=runtime();await assert.rejects(loadBundledFontCatalog({...absent.options,loadReceipt:async()=>{throw Error('staging missing');}}),/staging missing/);assert.equal(absent.calls.length,0);const failed=runtime({fail:2});await assert.rejects(loadBundledFontCatalog(failed.options),/decode rejected/);assert.equal(failed.doc.fonts.size,0);const controller=new AbortController(),cancelled=runtime({controller});await assert.rejects(loadBundledFontCatalog({...cancelled.options,signal:controller.signal}),/abort/i);assert.equal(cancelled.doc.fonts.size,0);await assert.rejects(loadBundledFontCatalog({...runtime().options,baseURL:'https://unrelated.example/fonts/'}),/same-origin/);});
test('document font ownership deduplicates consumers and preserves aliases beyond editor lifetime',async()=>{const f=runtime();const a=sharedBundledFontCatalog(f.options),b=sharedBundledFontCatalog(f.options);assert.equal(a,b);await a;assert.equal(f.calls.length,3);assert.equal(f.doc.fonts.size,3);});
class Node extends EventTarget{constructor(tag,doc){super();this.tagName=tag;this.ownerDocument=doc;this.children=[];this.attributes={};this.style={};this.value='';}append(...nodes){this.children.push(...nodes);}setAttribute(key,value){this.attributes[key]=value;}getAttribute(key){return this.attributes[key];}replaceChildren(){this.children=[];}querySelectorAll(tag){return this.children.flatMap(node=>[...(node.tagName===tag?[node]:[]),...node.querySelectorAll(tag)]);}setCustomValidity(){}reportValidity(){}remove(){}click(){return this.dispatchEvent(new Event('click'));}}
test('actual typed picker forwards verified Latin italic and Hong Kong aliases through one original mutation',async()=>{const f=runtime(),catalog=await loadBundledFontCatalog(f.options),doc={createElement:tag=>new Node(tag,doc)},host=new Node('host',doc),patches=[];const picker=mountFontPicker(host,{catalog,mutate:patch=>patches.push(patch)});for(const face of catalog.faces)await picker.applyFace(face.id);assert.equal(patches.length,3);assert.ok(patches[1].fontFamily.startsWith('"MFE Noto Sans Italic"'));assert.equal(patches[1].fontStyle,'italic');assert.ok(patches[2].fontFamily.startsWith('"MFE Noto Sans CJK HK"'));assert.equal(patches[2].fontWeight,'100');picker.destroy();catalog.destroy();});
test('root build and website staging preserve local fonts and exclude staging caches from packages',async()=>{const build=await fs.readFile(new URL('../scripts/build.ps1',import.meta.url),'utf8'),site=await fs.readFile(new URL('../scripts/build-site-workspace.mjs',import.meta.url),'utf8'),forge=await fs.readFile(new URL('../forge.config.cjs',import.meta.url),'utf8');assert.ok(build.indexOf('node scripts/stage-font-outputs.mjs')<build.indexOf('npm.cmd run package'));assert.ok(site.includes("stageFontOutputs({root,siteDirectory:path.join(destination,'fonts')})"));assert.ok(forge.includes('font-assets'));const app=await fs.readFile(new URL('../src/renderer/app.js',import.meta.url),'utf8'),publicShell=await fs.readFile(new URL('../docs/site/site-foundation.js',import.meta.url),'utf8'),adapter=await fs.readFile(new URL('../docs/site/visitor-personalization.js',import.meta.url),'utf8');assert.ok(app.includes("bundledFontBaseURL:new URL('./fonts/',import.meta.url).href"));assert.ok(publicShell.includes("bundledFontBaseURL:new URL('./fonts/',import.meta.url).href"));assert.ok(adapter.includes('bundledFontBaseURL:options.bundledFontBaseURL'));});

test('mounted picker rejects unavailable or unverified bundled regular faces before mutation and history',async()=>{
 const f=runtime(),loaded=await loadBundledFontCatalog(f.options),regular=loaded.faces[0];
 for(const patch of [{mapping:{...regular.mapping,verified:false}},{availability:'unavailable'},{mapping:{...regular.mapping,cssFamily:'Wrong alias'}},{cssFamily:'Wrong alias'}]){
  const face={...regular,...patch},catalog={faces:[face]},doc={createElement:tag=>new Node(tag,doc)},host=new Node('host',doc);let mutations=0,history=0;
  const picker=mountFontPicker(host,{catalog,mutate:()=>{mutations++;history++;}});
  await assert.rejects(picker.applyFace(face.id),/exact face mapping/);
  assert.equal(mutations,0);assert.equal(history,0);assert.equal(picker.getSelection(),null);picker.destroy();
 }
 loaded.destroy();
});